import{_ as i}from"./chunks/Audio.COine8Wh.js";import{c as n,o as r,j as t,G as a,ae as o,a as s}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse(`{"title":"Implementing the President's \\"department of government efficiency\\" cost efficiency initiative","description":"","frontmatter":{"legisId":"2025-02-26-implementing-the-presidents-department-of-government-efficiency-cost-efficiency-initiative","title":"Implementing the President's \\"department of government efficiency\\" cost efficiency initiative","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/02/implementing-the-presidents-department-of-government-efficiency-cost-efficiency-initiative/","publishDate":"2025-02-26","head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Executive Orders\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Implementing the President's \\\\\\"department of government efficiency\\\\\\" cost efficiency initiative\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders/2025-02-26-implementing-the-presidents-department-of-government-efficiency-cost-efficiency-initiative\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Implementing the President's \\\\\\"department of government efficiency\\\\\\" cost efficiency initiative\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/executive-orders/2025-02-26-implementing-the-presidents-department-of-government-efficiency-cost-efficiency-initiative\\",\\"datePublished\\":\\"2025-02-26\\",\\"dateModified\\":1770427707000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/executive-orders/2025-02-26-implementing-the-presidents-department-of-government-efficiency-cost-efficiency-initiative\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"executive-orders/2025-02-26-implementing-the-presidents-department-of-government-efficiency-cost-efficiency-initiative.md","filePath":"executive-orders/2025-02-26-implementing-the-presidents-department-of-government-efficiency-cost-efficiency-initiative.md","lastUpdated":1770427707000}`),c={name:"executive-orders/2025-02-26-implementing-the-presidents-department-of-government-efficiency-cost-efficiency-initiative.md"},p=Object.assign(c,{setup(l){return(d,e)=>(r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"implementing-the-president-s-department-of-government-efficiency-cost-efficiency-initiative",tabindex:"-1"},[s(`Implementing the President's "department of government efficiency" cost efficiency initiative `),t("a",{class:"header-anchor",href:"#implementing-the-president-s-department-of-government-efficiency-cost-efficiency-initiative","aria-label":`Permalink to "Implementing the President's "department of government efficiency" cost efficiency initiative"`},"​")],-1)),a(i),e[1]||(e[1]=o('<p>Published on Wednesday, February 26, 2025</p><h2 id="summary-of-executive-order-on-government-spending-transparency-and-efficiency" tabindex="-1">Summary of Executive Order on Government Spending Transparency and Efficiency <a class="header-anchor" href="#summary-of-executive-order-on-government-spending-transparency-and-efficiency" aria-label="Permalink to &quot;Summary of Executive Order on Government Spending Transparency and Efficiency&quot;">​</a></h2><h3 id="purpose" tabindex="-1"><strong>Purpose</strong> <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;**Purpose**&quot;">​</a></h3><ul><li>Aims to enhance <strong>transparency</strong> and <strong>accountability</strong> in <strong>Federal spending</strong> on contracts, grants, and loans.</li></ul><h3 id="key-definitions" tabindex="-1"><strong>Key Definitions</strong> <a class="header-anchor" href="#key-definitions" aria-label="Permalink to &quot;**Key Definitions**&quot;">​</a></h3><ul><li><strong>Administrator</strong> – Head of the U.S. DOGE Service.</li><li><strong>Agency</strong> – Federal departments except for the Executive Office of the President.</li><li><strong>Covered Contracts and Grants</strong> – Discretionary Federal spending excluding critical services (e.g., military, law enforcement).</li><li><strong>DOGE Team Lead</strong> – Oversees efficiency efforts within each agency.</li></ul><h3 id="measures-to-cut-costs" tabindex="-1"><strong>Measures to Cut Costs</strong> <a class="header-anchor" href="#measures-to-cut-costs" aria-label="Permalink to &quot;**Measures to Cut Costs**&quot;">​</a></h3><h4 id="_1-contract-and-grant-justification" tabindex="-1"><strong>1. Contract and Grant Justification</strong> <a class="header-anchor" href="#_1-contract-and-grant-justification" aria-label="Permalink to &quot;**1. Contract and Grant Justification**&quot;">​</a></h4><ul><li>Agencies must <strong>build a centralized system</strong> to record <strong>every payment</strong> with a justification.</li><li>Payments without justification can be <strong>paused and reviewed</strong>.</li><li>Payment justifications should be <strong>publicly posted</strong> where legally permissible.</li></ul><h4 id="_2-review-of-contracts-and-grants" tabindex="-1"><strong>2. Review of Contracts and Grants</strong> <a class="header-anchor" href="#_2-review-of-contracts-and-grants" aria-label="Permalink to &quot;**2. Review of Contracts and Grants**&quot;">​</a></h4><ul><li>Agencies must <strong>review existing contracts</strong> for potential <strong>termination, modification, or renegotiation</strong> to cut costs.</li><li>Focus on <strong>educational institutions and foreign entities</strong> for waste, fraud, and abuse.</li><li><strong>30-day deadline</strong> for review completion.</li></ul><h4 id="_3-contract-and-grant-process-review" tabindex="-1"><strong>3. Contract and Grant Process Review</strong> <a class="header-anchor" href="#_3-contract-and-grant-process-review" aria-label="Permalink to &quot;**3. Contract and Grant Process Review**&quot;">​</a></h4><ul><li>Agencies must <strong>review</strong> contracting policies, personnel, and procedures.</li><li><strong>New contract approvals paused</strong> for 30 days unless deemed necessary.</li></ul><h4 id="_4-contract-and-grant-approval" tabindex="-1"><strong>4. Contract and Grant Approval</strong> <a class="header-anchor" href="#_4-contract-and-grant-approval" aria-label="Permalink to &quot;**4. Contract and Grant Approval**&quot;">​</a></h4><ul><li>After review, agencies must issue <strong>guidance</strong> on <strong>new contracts</strong> to promote efficiency.</li><li>Monthly <strong>contracting activity reports</strong> to be sent to the Administrator.</li></ul><h4 id="_5-non-essential-travel-justification" tabindex="-1"><strong>5. Non-Essential Travel Justification</strong> <a class="header-anchor" href="#_5-non-essential-travel-justification" aria-label="Permalink to &quot;**5. Non-Essential Travel Justification**&quot;">​</a></h4><ul><li>Agencies must record <strong>federally funded travel</strong> justifications in a <strong>centralized system</strong>.</li><li>Travel without justification is prohibited.</li><li>Reports must be <strong>publicly posted</strong> where permissible.</li></ul><h4 id="_6-credit-card-freeze" tabindex="-1"><strong>6. Credit Card Freeze</strong> <a class="header-anchor" href="#_6-credit-card-freeze" aria-label="Permalink to &quot;**6. Credit Card Freeze**&quot;">​</a></h4><ul><li><strong>All government credit cards frozen for 30 days</strong>, except for disaster relief and critical services.</li></ul><h4 id="_7-real-property-management" tabindex="-1"><strong>7. Real Property Management</strong> <a class="header-anchor" href="#_7-real-property-management" aria-label="Permalink to &quot;**7. Real Property Management**&quot;">​</a></h4><ul><li>Agencies must update <strong>real property inventory</strong> within <strong>7 days</strong>.</li><li>Agencies must review <strong>lease termination rights</strong> within <strong>30 days</strong>.</li><li>A <strong>plan for disposal of unnecessary properties</strong> must be submitted within <strong>60 days</strong>.</li></ul><h3 id="general-exclusions" tabindex="-1"><strong>General Exclusions</strong> <a class="header-anchor" href="#general-exclusions" aria-label="Permalink to &quot;**General Exclusions**&quot;">​</a></h3><ul><li>Exemptions include <strong>law enforcement, military, immigration enforcement</strong>, and <strong>classified information</strong>.</li></ul><h3 id="general-provisions" tabindex="-1"><strong>General Provisions</strong> <a class="header-anchor" href="#general-provisions" aria-label="Permalink to &quot;**General Provisions**&quot;">​</a></h3><ul><li>Does <strong>not override existing laws</strong> or agency authorities.</li><li>Implementation subject to <strong>available funding</strong>.</li><li>Does <strong>not create enforceable legal rights</strong> for individuals.</li></ul><p><strong>Issued: February 26, 2025 – The White House</strong></p><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/02/implementing-the-presidents-department-of-government-efficiency-cost-efficiency-initiative/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/02/implementing-the-presidents-department-of-government-efficiency-cost-efficiency-initiative/</a></p>',27))]))}});export{m as __pageData,p as default};
